 function chair(p){const lift=p.fallen?0:.16;const frame=new T.Group(),body=new T.Group();frame.position.set(p.x,0,p.z);frame.rotation.y=p.yaw;frame.scale.setScalar(p.scale);frame.scale.y*=p.heightScale||1;body.rotation.z=p.fallen?Math.PI/2:0;frame.add(body);root.add(frame);
  for(const x of[-.20,.20]){tube(wood,[[x*1.13,0,.23],[x*1.03,.22,.19],[x,.47+lift,.17]],.018,body);tube(wood,[[x*1.17,0,-.24],[x,.47+lift,-.19],[x*.95,.81,-.23],[x*.92,1.20,-.29]],.018,body);}
  const seatShape=new T.Shape(),w=.43,d=.43,rr=.07;seatShape.moveTo(-w/2+rr,-d/2);seatShape.lineTo(w/2-rr,-d/2);seatShape.quadraticCurveTo(w/2,-d/2,w/2,-d/2+rr);seatShape.lineTo(w/2,d/2-rr);seatShape.quadraticCurveTo(w/2,d/2,w/2-rr,d/2);seatShape.lineTo(-w/2+rr,d/2);seatShape.quadraticCurveTo(-w/2,d/2,-w/2,d/2-rr);seatShape.lineTo(-w/2,-d/2+rr);seatShape.quadraticCurveTo(-w/2,-d/2,-w/2+rr,-d/2);
  const seat=new T.ExtrudeGeometry(seatShape,{depth:.028,bevelEnabled:true,bevelSize:.006,bevelThickness:.006,bevelSegments:2});seat.rotateX(-Math.PI/2);add(seat,wood,0,.443+lift,0,0,0,0,body);const woven=new T.ShapeGeometry(seatShape,12);const uv=woven.attributes.uv,pos=woven.attributes.position;for(let i=0;i<uv.count;i++)uv.setXY(i,pos.getX(i)/w+.5,pos.getY(i)/d+.5);woven.scale(.87,.87,1);add(woven,cane,0,.48+lift,0,-Math.PI/2,0,0,body);
  tube(wood,[[-.186,1.19,-.29],[-.13,1.222,-.292],[0,1.225,-.30],[.13,1.222,-.292],[.186,1.19,-.29]],.024,body);for(const x of[-.115,0,.115])tube(wood,[[x,.51+lift,-.19],[x*.9,.81,-.245],[x,1.20,-.29]],.010,body);
  tube(wood,[[-.20,.53+lift,-.16],[-.19,.65+lift,-.04],[0,.70+lift,.07],[.19,.65+lift,-.04],[.20,.53+lift,-.16]],.013,body);const ring=[];for(let i=0;i<=40;i++){const a=i/40*Math.PI*2;ring.push([Math.cos(a)*.194,.27,Math.sin(a)*.18]);}tube(wood,ring,.010,body);
  root.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(frame);frame.position.y-=bounds.min.y;frame.updateMatrixWorld(true);const bb=new T.Box3().setFromObject(frame);colliders.push({x:(bb.min.x+bb.max.x)/2-P.x,z:(bb.min.z+bb.max.z)/2-P.z,w:bb.max.x-bb.min.x,d:bb.max.z-bb.min.z});}
 CHAIRS.forEach(chair);
 function outlet(x,z,y,yaw){const o=new T.Group();o.position.set(x,y,z);o.rotation.y=yaw;root.add(o);box(ivory,0,0,.004,.071,.115,.009,o);for(const v of[-.027,.027]){box(ivory,0,v,.011,.043,.041,.006,o);for(const x of[-.008,.008])box(dark,x,v+.004,.015,.003,.013,.001,o);add(new T.CircleGeometry(.004,8),dark,0,v-.01,.015,0,0,0,o);}add(new T.CircleGeometry(.0025,8),brass,0,0,.013,0,0,0,o);}
 outlet(-3.993,.99,.34,Math.PI/2);outlet(-1.23,3.993,.55,Math.PI);outlet(-.66,3.993,.55,Math.PI);
 // Local contact skirts soften the wall-floor and furniture-foot junctions.
