 for(const c of colliders.filter(c=>!c.lintel)){add(new T.PlaneGeometry(c.w+.30,c.d+.30),ao,c.x,.008,c.z,-Math.PI/2,0,0,null,false);}
 const glow=new T.MeshBasicMaterial({color:0xf1eec2,toneMapped:false});box(glow,-6.94,1.35,-5.9,.018,2.35,1.12,null,false);
 function batch(g){const by=new Map();for(const o of [...g.children])if(o.isMesh){const k=o.material.uuid+o.castShadow;let b=by.get(k);if(!b){b={m:o.material,cast:o.castShadow,geos:[]};by.set(k,b);}o.updateMatrix();const geo=o.geometry.clone().applyMatrix4(o.matrix);b.geos.push(geo.index?geo.toNonIndexed():geo);g.remove(o);}for(const b of by.values()){const mesh=new T.Mesh(mergeGeometries(b.geos,false),b.m);mesh.castShadow=b.cast;mesh.receiveShadow=true;g.add(mesh);b.geos.forEach(x=>x.dispose());}for(const child of g.children)if(child.isGroup)batch(child);}
 batch(root);for(const p of pools.values()){const m=new T.Mesh(mergeGeometries(p.geos,false),p.m);m.castShadow=p.cast;m.receiveShadow=p.m!==ao;root.add(m);p.geos.forEach(g=>g.dispose());}
 function doorLocal(d,x,z){const dx=x-d.x,dz=z-d.z,c=Math.cos(d.yaw),s=Math.sin(d.yaw);return{x:c*dx-s*dz,z:s*dx+c*dz};}
